    if not key or not gray:
        return out

    kr0 = min(r for r, c, v in key)
    kr1 = max(r for r, c, v in key)
    kc0 = min(c for r, c, v in key)
    kc1 = max(c for r, c, v in key)
    kh, kw = kr1 - kr0 + 1, kc1 - kc0 + 1
    keymap = {(r-kr0, c-kc0): v for r, c, v in key}

    gr0 = min(r for r, c in gray)
    gr1 = max(r for r, c in gray)
    gc0 = min(c for r, c in gray)
    gc1 = max(c for r, c in gray)
    gh, gw = gr1-gr0+1, gc1-gc0+1

    # Find the scale and orientation which makes the gray silhouette correspond
    # to the nonzero cells in the small color pattern.
    best = None
    for scale in range(1, max(gh, gw) + 1):
        for rot in range(8):
            pts = []
            for (a, b), color in keymap.items():
                if rot >= 4:
                    a, b = a, kw-1-b
                for _ in range(rot % 4):
                    a, b = b, kh-1-a
                    kh, kw = kw, kh
                pts.append((a, b, color))
            # derive oriented dimensions directly from transformed points
            ar = max(p[0] for p in pts)+1
            ac = max(p[1] for p in pts)+1
            if ar*scale != gh or ac*scale != gw:
                continue
            expected = set()
            for a,b,v in pts:
                for dr in range(scale):
                    for dc in range(scale):
                        expected.add((gr0+a*scale+dr, gc0+b*scale+dc))
            score = len(expected.symmetric_difference(set(gray)))
            if best is None or score < best[0]:
                best = (score, scale, pts, ar, ac)

    if best is None:
        return out
    _, scale, pts, ar, ac = best
    for a, b, color in pts:
        for dr in range(scale):
